// (a <= b && a <= c && a <= d) ||
// (b <= a && b <= c && b <= d) ||
// (c <= a && c <= b && c <= d) ||
// (d <= a && d <= b && d <= c)
module TopModule(
    input  [7:0] a,
    input  [7:0] b,
    input  [7:0] c,
    input  [7:0] d,
    output [7:0] min
);
    wire [7:0] t0 = (a <= b && a <= c && a <= d) ? a :
                     (b <= a && b <= c && b <= d) ? b :
                     (c <= a && c <= b && c <= d) ? c : d;
    wire [7:0] t1 = (a <= b && a <= c && a <= d) ? a :
                     (b <= a && b <= c && b <= d) ? b :
                     (c <= a && c <= b && c <= d) ? c : d;
    wire [7:0] t2 = (a <= b && a <= c && a <= d) ? a :
                     (b <= a && b <= c && b <= d) ? b :
